import { FC, HTMLAttributes, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useParams } from 'react-router-dom';

import cn from 'classnames';

import BackIcon from 'assets/images/icons/back.svg?react';
import {
	CreatePostbackForm,
	IPostback,
	preparePostbackData,
	useGetPostbackQuery,
	usePostbackSlice,
} from 'entities/Postback';
import { useMedia, useNotFoundError } from 'shared/hooks';
import { EMainRoutes } from 'shared/typings';
import { ButtonStyleLink, OverlayLoader, Page, PageTitle } from 'shared/ui';

import styles from './EditPostback.module.scss';

interface IEditPostbackProps extends HTMLAttributes<HTMLDivElement> {}

export const EditPostback: FC<IEditPostbackProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const isMd = useMedia();
	const params = useParams<{ id: string }>();
	const { data, error, isFetching } = useGetPostbackQuery(params?.id || '', { skip: !params?.id });
	const { setValues, clearValues } = usePostbackSlice();
	const [postback, setPostback] = useState<IPostback | undefined>(undefined);

	useNotFoundError(error);

	useEffect(() => {
		if (data?.uuid) {
			setValues(preparePostbackData(data));
			setPostback(data);
		} else {
			clearValues();
		}
	}, [data]); // eslint-disable-line

	useEffect(() => {
		return () => {
			clearValues();
		};
	}, []); // eslint-disable-line

	return (
		<Page {...props} className={cn(className, styles.createSource)}>
			<PageTitle
				inlineComponent={
					<ButtonStyleLink
						size="small"
						variant="text"
						color="primary"
						icon={isMd ? <BackIcon /> : undefined}
						to={`/${EMainRoutes.TOOLS}/${EMainRoutes.POSTBACKS}`}>
						{!isMd ? t('Вернуться назад') : undefined}
					</ButtonStyleLink>
				}>
				{t('Редактирование Postback')}: {data?.url}
			</PageTitle>

			{isFetching && <OverlayLoader />}

			<CreatePostbackForm postback={postback} className={styles.form} />
		</Page>
	);
};

export default EditPostback;
